import { TaskRepository } from '../domain/TaskRepository';
import { ProjectRepository } from '../domain/ProjectRepository';
import { TaskEntity } from '../domain/Task';
import { CreateTaskRequest, CreateTaskResponse } from './dtos';

export class CreateTaskUseCase {
  constructor(
    private taskRepository: TaskRepository,
    private projectRepository: ProjectRepository,
  ) {}

  execute(request: CreateTaskRequest): CreateTaskResponse {
    const project = this.projectRepository.findById(request.projectId);
    if (!project) {
      throw new Error('Project not found');
    }

    const taskId = Math.random().toString(36).substring(2, 11);
    const task = new TaskEntity(
      taskId,
      request.projectId,
      request.title,
      request.description,
      request.dueDate,
      'todo',
    );
    this.taskRepository.save(task);

    return {
      id: task.id,
      projectId: task.projectId,
      title: task.title,
      description: task.description,
      dueDate: task.dueDate,
      status: task.status,
      assignedToUserId: task.assignedToUserId,
    };
  }
}

